'use client'

import { useState } from 'react'
import Link from 'next/link'
import { CardService } from '../../lib/CardService'

export default function CardPage() {
  const [playerName, setPlayerName] = useState('')
  const [year, setYear] = useState('')
  const [cardNumber, setCardNumber] = useState('')
  const [brand, setBrand] = useState('')
  const [loading, setLoading] = useState(false)
  const [cardData, setCardData] = useState(null)
  const [error, setError] = useState('')

  const handleSearch = async (e) => {
    e.preventDefault()

    if (!playerName.trim()) {
      setError('Please enter a player name')
      return
    }

    setLoading(true)
    setError('')

    try {
      const data = await CardService.searchCard({
        playerName: playerName.trim(),
        year: year.trim(),
        cardNumber: cardNumber.trim(),
        brand: brand.trim(),
      })
      setCardData(data)
    } catch (err) {
      setError('Failed to fetch card data. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  const formatCurrency = (value) => {
    if (!value && value !== 0) return 'N/A'
    return `$${parseFloat(value).toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`
  }

  const calculateUpgrade = () => {
    if (cardData?.rawPrice && cardData?.psa10Price) {
      const difference = cardData.psa10Price - cardData.rawPrice
      const percentage = ((difference / cardData.rawPrice) * 100).toFixed(0)
      return { difference, percentage }
    }
    return null
  }

  const upgrade = calculateUpgrade()

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <Link href="/" className="flex items-center space-x-2">
            <div className="text-3xl font-bold">
              <span className="text-blue-600">Up</span>
              <span className="text-gray-800">Grade</span>
            </div>
          </Link>
          <Link
            href="/"
            className="text-gray-600 hover:text-blue-600 font-medium"
          >
            Back to Home
          </Link>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-12">
        <div className="grid lg:grid-cols-2 gap-12">
          {/* Search Form */}
          <div>
            <div className="bg-white rounded-xl shadow-lg p-8">
              <h1 className="text-3xl font-bold text-gray-900 mb-2">
                Search for a Card
              </h1>
              <p className="text-gray-600 mb-8">
                Enter player details to see raw vs PSA 10 values
              </p>

              <form onSubmit={handleSearch} className="space-y-6">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Player Name <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    value={playerName}
                    onChange={(e) => setPlayerName(e.target.value)}
                    placeholder="e.g., Tom Brady"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Year
                  </label>
                  <input
                    type="text"
                    value={year}
                    onChange={(e) => setYear(e.target.value)}
                    placeholder="e.g., 2000"
                    maxLength="4"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Card Number
                  </label>
                  <input
                    type="text"
                    value={cardNumber}
                    onChange={(e) => setCardNumber(e.target.value)}
                    placeholder="e.g., 156"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Brand/Set
                  </label>
                  <input
                    type="text"
                    value={brand}
                    onChange={(e) => setBrand(e.target.value)}
                    placeholder="e.g., Topps Chrome"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
                  />
                </div>

                {error && (
                  <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
                    {error}
                  </div>
                )}

                <button
                  type="submit"
                  disabled={loading}
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-6 rounded-lg transition-all shadow-lg hover:shadow-xl disabled:bg-blue-300 disabled:cursor-not-allowed"
                >
                  {loading ? (
                    <span className="flex items-center justify-center">
                      <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Searching...
                    </span>
                  ) : (
                    'Search Card'
                  )}
                </button>
              </form>

              <div className="mt-8 p-4 bg-blue-50 rounded-lg">
                <p className="text-sm text-blue-900 font-semibold mb-2">💡 Quick Try:</p>
                <p className="text-xs text-blue-800">
                  Search for: Tom Brady, LeBron James, Michael Jordan, or Patrick Mahomes
                </p>
              </div>
            </div>
          </div>

          {/* Results */}
          <div>
            {cardData ? (
              <div className="bg-white rounded-xl shadow-lg overflow-hidden">
                {/* Card Header */}
                <div className="bg-gradient-to-r from-blue-600 to-blue-700 p-6 text-white">
                  <h2 className="text-3xl font-bold mb-2">{cardData.name}</h2>
                  <div className="flex flex-wrap gap-2 text-sm">
                    {cardData.year && (
                      <span className="bg-white/20 px-3 py-1 rounded-full">{cardData.year}</span>
                    )}
                    {cardData.brand && (
                      <span className="bg-white/20 px-3 py-1 rounded-full">{cardData.brand}</span>
                    )}
                    {cardData.cardNumber && (
                      <span className="bg-white/20 px-3 py-1 rounded-full">#{cardData.cardNumber}</span>
                    )}
                  </div>
                </div>

                <div className="p-8 space-y-6">
                  {/* Raw Price */}
                  <div className="border-l-4 border-gray-300 pl-6">
                    <div className="text-sm text-gray-500 uppercase font-semibold mb-1">
                      Raw Card Value
                    </div>
                    <div className="text-4xl font-bold text-gray-900">
                      {formatCurrency(cardData.rawPrice)}
                    </div>
                    <p className="text-sm text-gray-600 mt-1">Ungraded market value</p>
                  </div>

                  {/* PSA 10 Price */}
                  <div className="border-l-4 border-blue-600 pl-6">
                    <div className="text-sm text-blue-600 uppercase font-semibold mb-1 flex items-center gap-2">
                      PSA 10 Value
                      <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded text-xs">GEM MINT</span>
                    </div>
                    <div className="text-4xl font-bold text-blue-600">
                      {formatCurrency(cardData.psa10Price)}
                    </div>
                    <p className="text-sm text-blue-700 mt-1">Professionally graded</p>
                  </div>

                  {/* Upgrade Value */}
                  {upgrade && (
                    <div className="bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl p-6 border-2 border-green-200">
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-sm text-green-700 uppercase font-bold">
                          Potential UpGrade
                        </span>
                        <span className="text-lg text-green-600 font-bold bg-green-200 px-4 py-1 rounded-full">
                          +{upgrade.percentage}%
                        </span>
                      </div>
                      <div className="text-5xl font-bold text-green-600 mb-2">
                        +{formatCurrency(upgrade.difference)}
                      </div>
                      <p className="text-sm text-green-700">
                        If your card achieves a PSA 10 grade
                      </p>

                      <div className="mt-4 pt-4 border-t border-green-200">
                        <p className="text-xs text-green-800">
                          <strong>💰 ROI Analysis:</strong> Grading costs typically $50-150.
                          Your potential gain is {formatCurrency(upgrade.difference - 100)}.
                          {upgrade.difference > 500 ? ' Strong ROI potential!' : ' Consider grading costs carefully.'}
                        </p>
                      </div>
                    </div>
                  )}

                  {/* Source Info */}
                  {cardData.source && (
                    <div className="text-xs text-gray-500 pt-4 border-t border-gray-200">
                      <div className="flex justify-between items-center">
                        <span>Data source: {cardData.source}</span>
                        {cardData.lastUpdated && (
                          <span>Updated: {new Date(cardData.lastUpdated).toLocaleDateString()}</span>
                        )}
                      </div>
                    </div>
                  )}

                  <button
                    onClick={() => setCardData(null)}
                    className="w-full border-2 border-blue-600 text-blue-600 hover:bg-blue-50 font-semibold py-3 px-6 rounded-lg transition-all"
                  >
                    Search Another Card
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-white rounded-xl shadow-lg p-12 text-center">
                <div className="text-6xl mb-6">🔍</div>
                <h3 className="text-2xl font-bold text-gray-900 mb-2">
                  Ready to Search
                </h3>
                <p className="text-gray-600">
                  Enter a player name to see their card values
                </p>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  )
}
